CREATE FUNCTION c1_private.order_dto(n text,oid uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('id',o.id,'store',o.store,'quantity',o.quantity,'amount',o.amount::text,'terms',c1_private.term_dto(n,o.store,o.meal,o.version),'reported',(SELECT count(*) FROM c1_private.units WHERE ns=n AND order_id=o.id AND bucket IN('H','S')),'refunded',(SELECT count(*) FROM c1_private.units WHERE ns=n AND order_id=o.id AND bucket='X'),'paidAmount',(SELECT coalesce(sum(price),0)::text FROM c1_private.units WHERE ns=n AND order_id=o.id AND bucket='S'),'provenance',c1_private.provenance(n)) FROM c1_private.orders o WHERE o.ns=n AND o.id=oid $$;
CREATE FUNCTION c1_api.my_orders(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN PERFORM c1_private.cursor_guard(n,q);s=c1_private.auth(n,q);RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(c1_private.order_dto(n,id)),'[]') FROM (SELECT id FROM c1_private.orders WHERE ns=n AND subject=s.subject AND id::text>coalesce(q->>'after','') ORDER BY id LIMIT coalesce((q->>'limit')::int,20)) o),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.order_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN s=c1_private.auth(n,q);IF NOT EXISTS(SELECT 1 FROM c1_private.orders WHERE ns=n AND id=(q->>'id')::uuid AND subject=s.subject) THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN c1_private.order_dto(n,(q->>'id')::uuid);END $$;
CREATE FUNCTION c1_api.intent_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;i c1_private.intents;BEGIN s=c1_private.auth(n,q);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=(q->>'id')::uuid;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF i.principal<>s.subject THEN PERFORM c1_private.owner_auth(n,s,i.payload->>'store','redeem');END IF;RETURN jsonb_build_object('id',i.id,'stage',i.stage,'action',i.action,'result',i.result,'deadline',i.deadline,'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.workbench(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN s=c1_private.auth(n,q);PERFORM c1_private.owner_auth(n,s,q->>'store','redeem');RETURN jsonb_build_object('store',q->>'store','drafts',(SELECT coalesce(jsonb_agg(jsonb_build_object('meal',meal,'revision',revision,'name',convert_from(name,'UTF8')) ORDER BY meal),'[]') FROM c1_private.drafts WHERE ns=n AND store=q->>'store'),'financial',(SELECT totals FROM c1_private.rollups WHERE ns=n AND store=q->>'store'),'meals',(SELECT coalesce(jsonb_agg(c1_private.term_dto(n,store,meal,version)),'[]') FROM c1_private.catalog_head WHERE ns=n AND store=q->>'store'),'eligible',(SELECT count(*) FROM c1_private.units u JOIN c1_private.terms t USING(ns,store,meal,version) WHERE u.ns=n AND u.store=q->>'store' AND bucket='A' AND active_op IS NULL AND t.available),'controlRevision',(SELECT control_revision FROM c1_private.stores WHERE ns=n AND store=q->>'store'),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.case_get(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;u c1_private.units;BEGIN s=c1_private.auth(n,q);PERFORM c1_private.owner_auth(n,s,q->>'store','redeem');SELECT * INTO u FROM c1_private.units WHERE ns=n AND store=q->>'store' AND (lock_id=q->>'id' OR voucher_id=q->>'id');IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;RETURN jsonb_build_object('id',u.lock_id,'voucher',u.voucher_id,'state',u.bucket,'marked',u.marker_id IS NOT NULL,'markerAt',u.marker_at,'pending',u.active_op,'terms',c1_private.term_dto(n,u.store,u.meal,u.version),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.payouts(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE s c1_private.sessions;BEGIN
 PERFORM c1_private.cursor_guard(n,q);s=c1_private.auth(n,q);PERFORM c1_private.owner_auth(n,s,q->>'store','payout');
 RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',voucher_id,'amount',price::text,'state',bucket) ORDER BY voucher_id COLLATE "C"),'[]') FROM (SELECT voucher_id,price,bucket FROM c1_private.units WHERE ns=n AND store=q->>'store' AND bucket='H' AND voucher_id COLLATE "C">coalesce(q->>'after','') COLLATE "C" ORDER BY voucher_id COLLATE "C" LIMIT coalesce((q->>'limit')::int,20)) u),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.public_ledger(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE lim integer=coalesce((q->>'limit')::integer,20);BEGIN PERFORM c1_private.cursor_guard(n,q);IF lim<1 OR lim>50 THEN PERFORM c1_private.fail('PAGE_LIMIT');END IF;RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id::text,'store',store,'kind',kind,'amount',amount::text,'height',height)),'[]') FROM (SELECT * FROM c1_private.financial_entries WHERE ns=n AND id>coalesce((q->>'after')::bigint,0) AND height<=coalesce((q->>'snapshot')::bigint,(SELECT height FROM c1_private.deployment WHERE ns=n)) ORDER BY id LIMIT lim) l),'provenance',c1_private.provenance(n));END $$;
CREATE FUNCTION c1_api.rate_limit(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE nowv bigint;v jsonb;cnt integer;slot bigint;lim int;b bigint;s c1_private.sessions;payer text;bs jsonb=q->'buckets';k text;BEGIN IF coalesce((q->>'support')::boolean,false) THEN s=c1_private.auth(n,q,true);SELECT address INTO payer FROM c1_private.payer_bindings WHERE ns=n AND subject=s.subject;IF payer IS NULL THEN PERFORM c1_private.fail('PAYER_REQUIRED');END IF;FOREACH k IN ARRAY ARRAY['support-subject:'||s.subject,'support-payer:'||payer] LOOP bs=bs||jsonb_build_array(jsonb_build_object('key',k,'period',60,'limit',3),jsonb_build_object('key',k,'period',3600,'limit',10));END LOOP;END IF;SELECT now INTO nowv FROM c1_private.deployment WHERE ns=n;FOR v IN SELECT value FROM jsonb_array_elements(bs) LOOP slot=(v->>'period')::bigint;lim=(v->>'limit')::int;b=nowv/slot;INSERT INTO c1_private.rate_buckets VALUES(n,v->>'key',slot,b,1) ON CONFLICT(ns,key,period,bucket) DO UPDATE SET count=c1_private.rate_buckets.count+1 RETURNING count INTO cnt;IF cnt>lim THEN RETURN jsonb_build_object('error','RATE_LIMIT','status',429,'retryAfter',slot-nowv%slot);END IF;END LOOP;RETURN jsonb_build_object('allowed',true,'now',nowv);END $$;
CREATE FUNCTION c1_api.execution_fence(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN PERFORM c1_private.guard(n);IF NOT EXISTS(SELECT 1 FROM c1_private.dispatch_tickets WHERE ns=n AND intent=(q->>'ticket_id')::uuid) THEN PERFORM c1_private.fail('NOT_STAGED');END IF;UPDATE c1_private.transaction_guard SET execution_pending=q->>'ticket_id' WHERE ns=n AND security_pending IS NULL AND (execution_pending IS NULL OR execution_pending=q->>'ticket_id');IF NOT FOUND THEN PERFORM c1_private.fail('FENCE_PENDING');END IF;RETURN jsonb_build_object('reserved',true);END $$;
CREATE FUNCTION c1_api.execution_clear(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN PERFORM c1_private.guard(n);PERFORM c1_private.retain_journal(n,q);UPDATE c1_private.transaction_guard SET execution_pending=NULL WHERE ns=n AND execution_pending=q->>'ticket_id';RETURN jsonb_build_object('cleared',true);END $$;
